    auditLedger = pgTable13("audit_ledger", {
      id: serial13("id").primaryKey(),
      // Chain integrity
      previousHash: text13("previous_hash"),
      // Hash of previous record (null for genesis)
      currentHash: text13("current_hash").notNull().unique(),
      // SHA-256 hash of this record
      blockNumber: integer13("block_number").notNull().unique(),
      // Sequential block number (UNIQUE prevents forks)
      // Event data
      eventType: varchar13("event_type").notNull(),
      // wallet_generated, voucher_redeemed, loyalty_updated, discount_used, package_redeemed
      userId: varchar13("user_id").notNull(),
      // Who performed the action
      entityType: varchar13("entity_type").notNull(),
      // voucher, loyalty_card, discount, wash_package, wallet_pass
      entityId: varchar13("entity_id").notNull(),
      // ID of the entity being tracked
      // Transaction details
      action: varchar13("action").notNull(),
      // created, updated, redeemed, deleted, generated
      previousState: jsonb13("previous_state"),
      // State before change
      newState: jsonb13("new_state").notNull(),
      // State after change
      metadata: jsonb13("metadata").notNull().default(sql2`'{}'::jsonb`),
      // Additional context
      // Security & verification
      ipAddress: varchar13("ip_address"),
      userAgent: text13("user_agent"),
      deviceId: varchar13("device_id"),
      fraudScore: integer13("fraud_score").default(0),
      // 0-100 risk score
      fraudSignals: jsonb13("fraud_signals").default(sql2`'[]'::jsonb`),
      // Array of fraud indicators
      // Timestamp (immutable)
      createdAt: timestamp13("created_at").notNull().defaultNow(),
      // Verification status
      verified: boolean13("verified").default(true),
      // Hash chain verification status
      verifiedAt: timestamp13("verified_at")
    }, (table) => [
      index12("idx_audit_user").on(table.userId),
      index12("idx_audit_entity").on(table.entityType, table.entityId),
      index12("idx_audit_event").on(table.eventType),
      index12("idx_audit_created").on(table.createdAt),
      index12("idx_audit_block").on(table.blockNumber)
    ]);
