      // 'pending', 'accepted', 'rejected', 'blocked'
      acceptedAt: timestamp13("accepted_at"),
      rejectedAt: timestamp13("rejected_at"),
      createdAt: timestamp13("created_at").defaultNow(),
      updatedAt: timestamp13("updated_at").defaultNow()
