    petAwarenessDays = pgTable13("pet_awareness_days", {
      id: serial13("id").primaryKey(),
      // Event Identification
      slug: varchar13("slug").notNull().unique(),
      // 'international-dog-day', 'national-cat-day'
      eventDate: date11("event_date").notNull(),
      // Specific date (e.g., '2026-08-26')
      recurrenceType: varchar13("recurrence_type").default("annual"),
      // 'annual', 'monthly', 'weekly', 'one_time'
      // Multi-language Content (JSONB for localized strings)
      titleLocales: jsonb13("title_locales").notNull(),
      // { "en": "International Dog Day", "he": "יום הכלב הבינלאומי" }
      descriptionLocales: jsonb13("description_locales"),
      // { "en": "Celebrates all dogs...", "he": "חוגגים את כל הכלבים..." }
      // Event Metadata
      petTypes: text13("pet_types").array(),
      // ['dog'], ['cat'], ['dog', 'cat', 'bird']
      category: varchar13("category").notNull(),
      // 'celebration', 'awareness', 'health', 'adoption', 'memorial'
      isGlobal: boolean13("is_global").default(true),
      // True for international, false for country-specific
      targetCountries: text13("target_countries").array(),
      // ['IL', 'US', 'AU'] - null means all countries
      // Campaign Hook
      defaultCampaignType: varchar13("default_campaign_type"),
      // 'discount', 'awareness', 'donation', 'social'
      suggestedDiscountPercent: integer13("suggested_discount_percent"),
      // 10, 20, 30
      // Display
      heroImageUrl: varchar13("hero_image_url"),
      iconEmoji: varchar13("icon_emoji"),
      // 🐕, 🐈, 🐾
      themeColor: varchar13("theme_color"),
      // '#FF6B6B' for styling
      // Status
      isActive: boolean13("is_active").default(true),
      createdBy: varchar13("created_by"),
      createdAt: timestamp13("created_at").defaultNow(),
      updatedAt: timestamp13("updated_at").defaultNow()
    }, (table) => ({
      slugIdx: index12("idx_awareness_slug").on(table.slug),
      dateIdx: index12("idx_awareness_date").on(table.eventDate),
      categoryIdx: index12("idx_awareness_category").on(table.category)
    }));
    promotionalCampaigns = pgTable13("promotional_campaigns", {
      id: serial13("id").primaryKey(),
      // Campaign Basics
      name: varchar13("name").notNull(),
      slug: varchar13("slug").notNull().unique(),
      awarenessDayId: integer13("awareness_day_id").references(() => petAwarenessDays.id),
      // Status & Lifecycle
      status: varchar13("status").default("draft").notNull(),
      // 'draft', 'pending_review', 'approved', 'live', 'paused', 'expired', 'cancelled'
      startAt: timestamp13("start_at").notNull(),
      endAt: timestamp13("end_at").notNull(),
      // Targeting
      targetSegments: jsonb13("target_segments"),
      // { "loyaltyTiers": ["gold", "platinum"], "petTypes": ["dog"] }
      targetLocales: text13("target_locales").array(),
      // ['en', 'he', 'ar']
      targetCountries: text13("target_countries").array(),
      // ['IL', 'US']
      // Discount Configuration
      discountType: varchar13("discount_type").notNull(),
      // 'percentage', 'fixed', 'bundle', 'referral', 'bogo'
      discountValue: decimal11("discount_value", { precision: 10, scale: 2 }).notNull(),
      // 20.00 for 20%, or 50.00 for ₪50
      discountCurrency: varchar13("discount_currency").default("ILS"),
      // For fixed discounts
      maxRedemptions: integer13("max_redemptions"),
      // null = unlimited
      currentRedemptions: integer13("current_redemptions").default(0),
      minPurchaseAmount: decimal11("min_purchase_amount", { precision: 10, scale: 2 }),
      maxDiscountAmount: decimal11("max_discount_amount", { precision: 10, scale: 2 }),
      // Cap for percentage discounts
      // Promo Code
      promoCode: varchar13("promo_code"),
      // 'DOGDAY2026'
      isAutoApply: boolean13("is_auto_apply").default(false),
      // Auto-apply at checkout
      // Content (Multi-language)
      contentLocales: jsonb13("content_locales").notNull(),
      // { "en": { "title": "...", "description": "..." }, "he": { ... } }
      heroAssets: jsonb13("hero_assets"),
      // { "desktop": "url", "mobile": "url" }
      // Social Boost
      socialBoostEnabled: boolean13("social_boost_enabled").default(false),
      socialBoostBudget: decimal11("social_boost_budget", { precision: 10, scale: 2 }),
      scheduledPostIds: jsonb13("scheduled_post_ids"),
      // [123, 456] - social post IDs to boost
      // Approval
      requiresManualReview: boolean13("requires_manual_review").default(true),
      reviewedBy: varchar13("reviewed_by"),
      reviewedAt: timestamp13("reviewed_at"),
      reviewNotes: text13("review_notes"),
      // Creator & Audit
      createdBy: varchar13("created_by").notNull(),
      approvedBy: varchar13("approved_by"),
      createdAt: timestamp13("created_at").defaultNow(),
      updatedAt: timestamp13("updated_at").defaultNow()
    }, (table) => ({
      slugIdx: index12("idx_campaign_slug").on(table.slug),
      statusIdx: index12("idx_campaign_status").on(table.status),
      startAtIdx: index12("idx_campaign_start").on(table.startAt),
      promoCodeIdx: index12("idx_campaign_promo").on(table.promoCode)
    }));
