    taxRateHistory = pgTable13("tax_rate_history", {
      id: serial13("id").primaryKey(),
      // Tax Type
      taxType: varchar13("tax_type").notNull(),
      // 'vat', 'municipal', 'corporate', 'customs'
      // Rate Information
      rate: decimal11("rate", { precision: 5, scale: 4 }).notNull(),
      // 0.1800 (18%), 0.0000 (0%)
      ratePercent: decimal11("rate_percent", { precision: 5, scale: 2 }).notNull(),
      // 18.00, 0.00 (for display)
      // Applicability
      category: varchar13("category"),
      // 'standard', 'zero_rate', 'exempt', 'reduced', 'export'
      description: text13("description"),
      // 'Standard VAT Rate'
      descriptionHe: text13("description_he"),
      // 'שיעור מע"מ רגיל'
      // Temporal Validity
      effectiveFrom: date11("effective_from").notNull(),
      // Date when this rate becomes active
      effectiveTo: date11("effective_to"),
      // Date when this rate expires (null = current)
      // Regulatory Source
      regulatorySource: text13("regulatory_source"),
      // 'Israeli Tax Authority Directive 2025/04'
      regulatoryUrl: text13("regulatory_url"),
      // Link to official announcement
      // Metadata
      isActive: boolean13("is_active").default(true),
      createdBy: varchar13("created_by"),
      // Admin who added this rate
      createdAt: timestamp13("created_at").defaultNow(),
      updatedAt: timestamp13("updated_at").defaultNow()
    }, (table) => ({
      taxTypeIdx: index12("idx_tax_type").on(table.taxType),
      effectiveFromIdx: index12("idx_effective_from").on(table.effectiveFrom),
      activeIdx: index12("idx_active").on(table.isActive)
    }));
    expenses = pgTable13("expenses", {
      id: serial13("id").primaryKey(),
      // Employee & Organization
      employeeId: varchar13("employee_id").notNull(),
      // Firebase UID
      employeeName: varchar13("employee_name").notNull(),
      employeeEmail: varchar13("employee_email").notNull(),
      businessId: varchar13("business_id").default("petwash-ltd").notNull(),
      departmentId: varchar13("department_id"),
      // For multi-department companies
      // Date & Period
      expenseDate: date11("expense_date").notNull(),
      // Date on receipt
      reportPeriod: varchar13("report_period").notNull(),
      // 'YYYY-MM' for tax reporting
      // Amounts (ILS)
      totalAmountILS: decimal11("total_amount_ils", { precision: 10, scale: 2 }).notNull(),
      // Gross amount (כולל מע"מ)
      netAmountILS: decimal11("net_amount_ils", { precision: 10, scale: 2 }).notNull(),
      // Net amount (ללא מע"מ)
      vatAmountILS: decimal11("vat_amount_ils", { precision: 10, scale: 2 }).notNull(),
      // VAT amount (סכום מע"מ)
      // Dynamic Tax Rates (NOT HARDCODED)
      vatRateApplied: decimal11("vat_rate_applied", { precision: 5, scale: 4 }).notNull(),
      // Actual VAT rate used (0.1800, 0.0000)
      vatExemptionReason: varchar13("vat_exemption_reason"),
      // 'zero_rate_export', 'exempt_education', 'exempt_flight'
      municipalTaxRate: decimal11("municipal_tax_rate", { precision: 5, scale: 4 }),
      // Municipal taxes (ארנונה, etc.)
      municipalTaxAmount: decimal11("municipal_tax_amount", { precision: 10, scale: 2 }),
      // Tax Deductibility
      isTaxDeductible: boolean13("is_tax_deductible").default(true),
      deductibilityReason: text13("deductibility_reason"),
      // Why deductible or not
      // Category
      category: varchar13("category").notNull(),
      // 'meals', 'travel', 'office_supplies', 'training', 'accommodation', 'mileage', 'entertainment', 'other'
      subcategory: varchar13("subcategory"),
      // More granular categorization
      description: text13("description").notNull(),
      // User description
      // Receipt & Proof
      receiptImageUrls: text13("receipt_image_urls").array(),
      // Multiple receipt images
      receiptOcrText: text13("receipt_ocr_text"),
      // Extracted text from OCR
      receiptVendorName: varchar13("receipt_vendor_name"),
      // Vendor extracted from OCR
      receiptVendorTaxId: varchar13("receipt_vendor_tax_id"),
      // Israeli Tax ID (מספר עוסק מורשה)
      // Status & Approval Workflow
      status: varchar13("status").default("draft").notNull(),
      // 'draft', 'pending', 'approved', 'rejected', 'reimbursed'
      submittedAt: timestamp13("submitted_at"),
      // Approver Chain
      approverId: varchar13("approver_id"),
      // Manager/supervisor
      approverName: varchar13("approver_name"),
      approvedAt: timestamp13("approved_at"),
      rejectionReason: text13("rejection_reason"),
      // Policy Compliance
      policyViolations: jsonb13("policy_violations"),
      // Array of violation objects
      policyStatus: varchar13("policy_status").default("compliant"),
      // 'compliant', 'warning', 'violation'
      // Mileage (if applicable)
      mileageKm: decimal11("mileage_km", { precision: 10, scale: 2 }),
      mileageRatePerKm: decimal11("mileage_rate_per_km", { precision: 5, scale: 2 }),
      // Location Data
      locationName: varchar13("location_name"),
      // Where expense occurred
      locationCoordinates: varchar13("location_coordinates"),
      // Lat/Long for verification
      // Reimbursement
      reimbursementStatus: varchar13("reimbursement_status").default("pending"),
      // 'pending', 'processed', 'paid'
      reimbursementDate: date11("reimbursement_date"),
      reimbursementMethod: varchar13("reimbursement_method"),
      // 'bank_transfer', 'payroll', 'check'
      // Audit Trail
      ipAddress: varchar13("ip_address"),
      userAgent: varchar13("user_agent"),
      lastModifiedBy: varchar13("last_modified_by"),
      createdAt: timestamp13("created_at").defaultNow(),
      updatedAt: timestamp13("updated_at").defaultNow()
    }, (table) => ({
      employeeIdx: index12("idx_expense_employee").on(table.employeeId),
      statusIdx: index12("idx_expense_status").on(table.status),
      dateIdx: index12("idx_expense_date").on(table.expenseDate),
      reportPeriodIdx: index12("idx_expense_period").on(table.reportPeriod),
      approverIdx: index12("idx_expense_approver").on(table.approverId)
    }));
