      moderationNotes: text13("moderation_notes"),
      moderationStatus: varchar13("moderation_status").default("pending"),
      // pending | approved | removed
      // Verification (Ensures only real customers/contractors can review)
      isVerifiedBooking: boolean13("is_verified_booking").default(true),
      // Booking must be completed
      verificationMethod: varchar13("verification_method"),
      // blockchain | payment | gps
      // Visibility & Status
      isVisible: boolean13("is_visible").default(true),
      // Can be hidden by admin
      isPublic: boolean13("is_public").default(true),
      // Public on profile
      // Trust Score Impact (Calculated by AI Trust Scoring Engine)
      trustScoreImpact: decimal11("trust_score_impact", { precision: 5, scale: 2 }),
      // -1.00 to +1.00
      createdAt: timestamp13("created_at").defaultNow(),
      updatedAt: timestamp13("updated_at").defaultNow()
