    bookingRequestStatusEnum = pgEnum("booking_request_status", [
      "pending",
      // Initial request sent to provider
      "accepted",
      // Provider accepted, awaiting meet & greet
      "declined",
      // Provider declined the request
      "meet_greet_scheduled",
      // Meet & Greet date set
      "meet_greet_completed",
      // Meet & Greet done, awaiting payment
      "payment_pending",
      // Awaiting payment from owner
      "confirmed",
      // Payment received, booking confirmed
      "in_progress",
      // Service currently happening
      "completed",
      // Service completed, pending review
      "reviewed",
      // Owner left review
      "cancelled",
      // Cancelled by either party
      "disputed"
      // Payment/service dispute
    ]);
    bookingRequests = pgTable13("booking_requests", {
      id: serial13("id").primaryKey(),
      requestId: varchar13("request_id", { length: 24 }).notNull().unique(),
      // Nanoid for public reference
      // Parties
      ownerId: varchar13("owner_id", { length: 128 }).notNull(),
      // Pet owner Firebase UID
      providerId: varchar13("provider_id", { length: 128 }).notNull(),
      // Service provider Firebase UID
      providerProfileId: integer13("provider_profile_id"),
      // Sitter/Walker profile ID
      providerType: varchar13("provider_type", { length: 32 }).notNull(),
      // sitter, walker, trainer, driver, k9000
      // Service details
      serviceType: varchar13("service_type", { length: 32 }).notNull(),
      // pet_sitting, dog_walking, etc.
      startDate: timestamp13("start_date").notNull(),
      endDate: timestamp13("end_date").notNull(),
      // Pet information
      petIds: text13("pet_ids").array(),
      // Array of pet profile IDs
      petCount: integer13("pet_count").notNull().default(1),
      petDetails: jsonb13("pet_details"),
      // Cached pet info for reference
      // Pricing
      dailyRateCents: integer13("daily_rate_cents"),
      hourlyRateCents: integer13("hourly_rate_cents"),
      totalDays: integer13("total_days"),
      totalHours: decimal11("total_hours"),
      subtotalCents: integer13("subtotal_cents").notNull(),
      serviceFeePercent: decimal11("service_fee_percent").default("15"),
      // 15% platform fee
      serviceFeeCents: integer13("service_fee_cents").notNull(),
      totalCents: integer13("total_cents").notNull(),
      currency: varchar13("currency", { length: 3 }).default("ILS").notNull(),
      // Status tracking
      status: bookingRequestStatusEnum("status").default("pending").notNull(),
      statusHistory: jsonb13("status_history").default([]),
      // [{status, timestamp, note}]
      // Meet & Greet
      meetGreetDate: timestamp13("meet_greet_date"),
      meetGreetLocation: text13("meet_greet_location"),
      meetGreetNotes: text13("meet_greet_notes"),
      meetGreetCompletedAt: timestamp13("meet_greet_completed_at"),
      // Messages
      ownerMessage: text13("owner_message"),
      // Initial request message
      providerResponse: text13("provider_response"),
      specialRequirements: text13("special_requirements"),
      // Payment
      paymentMethod: varchar13("payment_method", { length: 32 }),
      // nayax, apple_pay, etc.
      paymentTransactionId: varchar13("payment_transaction_id", { length: 64 }),
      paymentHeldAt: timestamp13("payment_held_at"),
      // Escrow start
      paymentReleasedAt: timestamp13("payment_released_at"),
      // Payment to provider
      // Service tracking
      serviceStartedAt: timestamp13("service_started_at"),
      serviceCompletedAt: timestamp13("service_completed_at"),
      photoUpdates: jsonb13("photo_updates").default([]),
      // [{url, caption, timestamp}]
      // Completion & Review
      ownerConfirmedAt: timestamp13("owner_confirmed_at"),
      ownerRating: decimal11("owner_rating"),
      ownerReview: text13("owner_review"),
      providerRating: decimal11("provider_rating"),
      // Provider rates owner
      providerReview: text13("provider_review"),
      // Cancellation
      cancelledAt: timestamp13("cancelled_at"),
      cancelledBy: varchar13("cancelled_by", { length: 16 }),
      // owner, provider, system
      cancellationReason: text13("cancellation_reason"),
      refundCents: integer13("refund_cents"),
      refundProcessedAt: timestamp13("refund_processed_at"),
      // Metadata
      searchId: varchar13("search_id", { length: 24 }),
      // Link to original search
      createdAt: timestamp13("created_at").defaultNow().notNull(),
      updatedAt: timestamp13("updated_at").defaultNow().notNull()
    });
