      id: varchar13("id").primaryKey(),
      // UV-YYYYMMDD-XXXXXXXX
      // --- Classification ---
      voucherType: varchar13("voucher_type", { length: 32 }).notNull(),
      // WASH_PACKAGE | PLATFORM_CREDIT
      designTheme: varchar13("design_theme", { length: 32 }).notNull().default("pink"),
      // pink | green | black | gold
      status: varchar13("status", { length: 32 }).notNull().default("ISSUED"),
      // ISSUED | ACTIVE | PARTIALLY_REDEEMED | REDEEMED | EXPIRED | CANCELLED
      // --- Stored Value ---
      // For WASH_PACKAGE: washesOriginal / washesRemaining are used; value fields = null
      // For PLATFORM_CREDIT: value fields are used; washes fields = null
      currency: varchar13("currency", { length: 8 }).notNull().default("ILS"),
      valueOriginal: decimal11("value_original", { precision: 12, scale: 2 }),
      // ILS amount (PLATFORM_CREDIT)
      valueRemaining: decimal11("value_remaining", { precision: 12, scale: 2 }),
