      serviceTypes: text14("service_types").array().notNull(),
      // Array of service types
      yearsExperience: integer14("years_experience").default(0),
      certifications: text14("certifications").array(),
      // Pet first aid, grooming certs, etc.
      biography: text14("biography"),
      // About themselves
      languages: text14("languages").array().default(sql3`ARRAY['he']::text[]`),
      // Service Preferences
      serviceRadius: integer14("service_radius").default(10),
      // km
      maxPetsAtOnce: integer14("max_pets_at_once").default(3),
      petTypesAccepted: text14("pet_types_accepted").array().default(sql3`ARRAY['dog', 'cat']::text[]`),
      hasOwnVehicle: boolean14("has_own_vehicle").default(false),
      hasHomeSpace: boolean14("has_home_space").default(false),
      // For pet sitting
      // Emergency Contact
      emergencyContactName: varchar14("emergency_contact_name"),
      emergencyContactPhone: varchar14("emergency_contact_phone"),
      emergencyContactRelation: varchar14("emergency_contact_relation"),
      // Application Status
      stage: varchar14("stage").notNull().default("application_submitted"),
      status: varchar14("status").notNull().default("pending"),
      // pending, approved, rejected, withdrawn
      rejectionReason: text14("rejection_reason"),
      // Interview/Screening
      interviewScheduledAt: timestamp14("interview_scheduled_at"),
      interviewCompletedAt: timestamp14("interview_completed_at"),
      interviewNotes: text14("interview_notes"),
      interviewScore: integer14("interview_score"),
      // 1-10
      // Admin Assignment
      assignedReviewerId: varchar14("assigned_reviewer_id"),
      // Admin UID
      reviewerNotes: text14("reviewer_notes"),
      // Israeli Privacy Law 2025 Compliance
      privacyConsentAt: timestamp14("privacy_consent_at"),
      privacyConsentIp: varchar14("privacy_consent_ip"),
      marketingConsentAt: timestamp14("marketing_consent_at"),
      dataRetentionAcknowledgedAt: timestamp14("data_retention_acknowledged_at"),
      // Invitation (on approval)
      invitationToken: varchar14("invitation_token").unique(),
      invitationSentAt: timestamp14("invitation_sent_at"),
      invitationExpiresAt: timestamp14("invitation_expires_at"),
      onboardingCompletedAt: timestamp14("onboarding_completed_at"),
      // Audit Trail
      submittedAt: timestamp14("submitted_at").defaultNow(),
      lastUpdatedAt: timestamp14("last_updated_at").defaultNow(),
      stageChangedAt: timestamp14("stage_changed_at").defaultNow(),
      approvedAt: timestamp14("approved_at"),
      rejectedAt: timestamp14("rejected_at"),
      // Cryptographic Integrity (Israeli Privacy Law 2025)
