  const subject = isHebrew ? `\u05D1\u05E8\u05D5\u05DB\u05D9\u05DD \u05D4\u05D1\u05D0\u05D9\u05DD \u05DC-\u2066Pet Wash\u2122\u2069, ${firstName}! \u{1F43E}` : `Welcome to \u2066Pet Wash\u2122\u2069, ${firstName}! \u{1F43E}`;
