function getTierBenefitsForUpgrade(tier, lang) {
  const config = TIER_CONFIGS.find((t3) => t3.id === tier);
  if (!config) return [];
  if (lang === "he") {
    const items2 = [];
    if (config.benefits.tierBonusPercent > 0) items2.push({ title: `${config.benefits.tierBonusPercent}% \u05D4\u05E0\u05D7\u05D4 \u05E0\u05D5\u05E1\u05E4\u05EA`, desc: "\u05E2\u05DC \u05D2\u05D1\u05D9 \u05D4\u05E0\u05D7\u05EA \u05D4\u05D7\u05D1\u05E8 \u05D4\u05D1\u05E1\u05D9\u05E1\u05D9\u05EA." });
    if (config.benefits.pointsMultiplier > 1) items2.push({ title: `\u05DE\u05DB\u05E4\u05D9\u05DC \u05E0\u05E7\u05D5\u05D3\u05D5\u05EA x${config.benefits.pointsMultiplier}`, desc: "\u05E6\u05D1\u05E8\u05D5 \u05E0\u05E7\u05D5\u05D3\u05D5\u05EA \u05DE\u05D4\u05E8 \u05D9\u05D5\u05EA\u05E8 \u05E2\u05DC \u05DB\u05DC \u05E9\u05D8\u05D9\u05E4\u05D4." });
    if (config.benefits.freeWashesPerYear > 0) items2.push({ title: `${config.benefits.freeWashesPerYear} \u05E9\u05D8\u05D9\u05E4\u05D5\u05EA \u05D7\u05D9\u05E0\u05DD \u05D1\u05E9\u05E0\u05D4`, desc: "\u05DE\u05EA\u05E0\u05D4 \u05DE\u05D4\u05DE\u05D5\u05E2\u05D3\u05D5\u05DF \u05E2\u05D1\u05D5\u05E8\u05DB\u05DD." });
    if (config.benefits.prioritySupport) items2.push({ title: "\u05EA\u05DE\u05D9\u05DB\u05D4 \u05D1\u05E2\u05D3\u05D9\u05E4\u05D5\u05EA", desc: "\u05DE\u05E2\u05E0\u05D4 \u05DE\u05D4\u05D9\u05E8 \u05D5\u05DE\u05D5\u05E2\u05D3\u05E3." });
    if (config.benefits.exclusiveAccess) items2.push({ title: "\u05D2\u05D9\u05E9\u05D4 \u05D1\u05DC\u05E2\u05D3\u05D9\u05EA", desc: "\u05D2\u05D9\u05E9\u05D4 \u05DE\u05D5\u05E7\u05D3\u05DE\u05EA \u05DC\u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05D5\u05E9\u05D9\u05E8\u05D5\u05EA\u05D9\u05DD \u05D7\u05D3\u05E9\u05D9\u05DD." });
    if (config.benefits.conciergeService) items2.push({ title: "\u05E9\u05D9\u05E8\u05D5\u05EA \u05E7\u05D5\u05E0\u05E1\u05D9\u05D9\u05E8\u05D6\u05F3", desc: "\u05E9\u05D9\u05E8\u05D5\u05EA \u05D0\u05D9\u05E9\u05D9 \u05D5\u05DE\u05D5\u05EA\u05D0\u05DD." });
    items2.push({ title: `${config.benefits.birthdayBonus} \u05E0\u05E7\u05D5\u05D3\u05D5\u05EA \u05D9\u05D5\u05DD \u05D4\u05D5\u05DC\u05D3\u05EA`, desc: "\u05D1\u05D5\u05E0\u05D5\u05E1 \u05DE\u05D9\u05D5\u05D7\u05D3 \u05D1\u05D9\u05D5\u05DD \u05D4\u05D4\u05D5\u05DC\u05D3\u05EA \u05E9\u05DC\u05DA." });
    return items2;
  }
  const items = [];
  if (config.benefits.tierBonusPercent > 0) items.push({ title: `${config.benefits.tierBonusPercent}% Extra Discount`, desc: "On top of your base club discount." });
  if (config.benefits.pointsMultiplier > 1) items.push({ title: `${config.benefits.pointsMultiplier}x Points Multiplier`, desc: "Earn points faster on every wash." });
  if (config.benefits.freeWashesPerYear > 0) items.push({ title: `${config.benefits.freeWashesPerYear} Free Washes/Year`, desc: "A gift from the club for you." });
  if (config.benefits.prioritySupport) items.push({ title: "Priority Support", desc: "Fast and preferred response." });
  if (config.benefits.exclusiveAccess) items.push({ title: "Exclusive Access", desc: "Early access to new products and services." });
  if (config.benefits.conciergeService) items.push({ title: "Concierge Service", desc: "Personal and tailored service." });
  items.push({ title: `${config.benefits.birthdayBonus} Birthday Points`, desc: "Special bonus on your birthday." });
  return items;
}
