function detectTierUpgrade(previousLifetimePoints, newLifetimePoints) {
  const tiers = TIER_CONFIGS.map((t3) => ({ id: t3.id, threshold: t3.threshold })).sort((a, b) => b.threshold - a.threshold);
  const previousTier = tiers.find((t3) => previousLifetimePoints >= t3.threshold)?.id || "bronze";
  const newTier = tiers.find((t3) => newLifetimePoints >= t3.threshold)?.id || "bronze";
  return {
    upgraded: previousTier !== newTier,
    previousTier,
    newTier
  };
}
