async function getBucketStats(storage11, bucketName3) {
  try {
    const [files] = await storage11.bucket(bucketName3).getFiles();
    let totalSize = 0;
    let oldestDate = null;
    let newestDate = null;
    files.forEach((file) => {
      const metadata = file.metadata;
      totalSize += parseInt(metadata.size || "0", 10);
      const created = new Date(metadata.timeCreated);
      if (!oldestDate || created < oldestDate) oldestDate = created;
      if (!newestDate || created > newestDate) newestDate = created;
    });
    return {
      fileCount: files.length,
      totalSizeGB: Number((totalSize / 1024 ** 3).toFixed(2)),
      oldestFile: oldestDate?.toISOString().split("T")[0] || "N/A",
      newestFile: newestDate?.toISOString().split("T")[0] || "N/A"
    };
  } catch (error) {
    logger.warn(`[Backup Report] Could not access bucket ${bucketName3}`, error);
    return {
      fileCount: 0,
      totalSizeGB: 0,
      oldestFile: "N/A",
      newestFile: "N/A"
    };
  }
}
