      const bearerToken = req.headers.authorization?.startsWith("Bearer ") ? req.headers.authorization.split("Bearer ")[1] : null;
      if (!token && !bearerToken) {
        return res.status(401).json({ authenticated: false, error: "no-session" });
      }
      let decoded;
